-- ===== 10. 自检SQL =====
-- 检查1: 角色数=5
SELECT CASE WHEN COUNT(*)=5 THEN 'PASS: Role=5' ELSE 'FAIL' END AS Check1 FROM Sys_Role WHERE IsDeleted=0;
-- 检查2: UserRole.UserId 全有效
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: All UserId valid' ELSE 'FAIL' END AS Check2 FROM Sys_UserRole ur LEFT JOIN Sys_User u ON ur.UserId=u.Id WHERE u.Id IS NULL;
-- 检查3: UserRole.RoleId 全有效
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: All RoleId valid' ELSE 'FAIL' END AS Check3 FROM Sys_UserRole ur LEFT JOIN Sys_Role r ON ur.RoleId=r.Id WHERE r.Id IS NULL;
-- 检查4: 权限码唯一
SELECT CASE WHEN COUNT(*)=COUNT(DISTINCT PermissionCode) THEN 'PASS: PermissionCode unique' ELSE 'FAIL' END AS Check4 FROM Sys_Permission WHERE IsDeleted=0;
-- 检查5: 未读通知=10
SELECT CASE WHEN COUNT(*)=10 THEN 'PASS: Unread=10' ELSE 'FAIL' END AS Check5 FROM Sys_Notification WHERE IsRead=0;
-- 检查6: 每个用户有角色
SELECT CASE WHEN COUNT(DISTINCT u.Id)=10 THEN 'PASS: 10 users in roles' ELSE 'FAIL' END AS Check6 FROM Sys_User u INNER JOIN Sys_UserRole ur ON u.Id=ur.UserId WHERE u.IsDeleted=0;
-- 检查7: 密码历史=10
SELECT CASE WHEN COUNT(*)=10 THEN 'PASS: PwdHistory=10' ELSE 'FAIL' END AS Check7 FROM Sys_PasswordHistory;
-- 检查8: Log UserId 全有效
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS: All Log UserId valid' ELSE 'FAIL' END AS Check8 FROM Sys_OperationLog ol LEFT JOIN Sys_User u ON ol.UserId=u.Id WHERE u.Id IS NULL;

COMMIT TRANSACTION;
END TRY
BEGIN CATCH
ROLLBACK TRANSACTION;
THROW;
END CATCH;

